const newItems = [];

for (const item of $input.all()) {
  try {
    // 1. Get the raw string from the AI Agent
    const rawOutput = item.json.output || item.json.text || "";

    // 2. Split into the Summary and the JSON parts
    const parts = rawOutput.split('||');

    // Clean up the summary
    let summaryText = parts[0].trim();
    summaryText = summaryText.replace(/^"|"$/g, '').trim(); 

    // 3. Clean up the JSON string using Regex
    let jsonString = parts[1].trim();
    const jsonMatch = jsonString.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      jsonString = jsonMatch[0];
    }

    // 4. Parse the extracted string into a real JSON object
    const parsedData = JSON.parse(jsonString);

    // Extract specific confidence scores to put at root level
    const confRain = parsedData.confidence_rain !== undefined ? parsedData.confidence_rain : null;
    const confWind = parsedData.confidence_wind !== undefined ? parsedData.confidence_wind : null;

    // Remove them from the features object so they don't appear twice
    delete parsedData.confidence_rain;
    delete parsedData.confidence_wind;
    delete parsedData.confidence; // Clean up generic confidence if it exists

    // 5. Build the final structure
    newItems.push({
      json: {
        summary: summaryText,
        features: parsedData,
        confidence_rain: confRain,
        confidence_wind: confWind
      }
    });

  } catch (error) {
    // Failsafe structure
    newItems.push({
      json: {
        summary: "AI output parsing failed: " + error.message,
        features: {
          rain_detected: null,
          water_on_leaves: null,
          cloud_cover: null,
          lighting_level: null,
          shadows_present: null,
          plant_motion_detected: null,
          motion_intensity: null
        },
        confidence_rain: null,
        confidence_wind: null
      }
    });
  }
}

return newItems;

const input = $input.all()[0].json;

function extractActuator(actuator) {
  return {
    type: actuator.type,
    classification: actuator.classification ?? null,
    control_mode: actuator.control_mode,
    skipped: actuator.skipped ?? false,
    re_evaluation: {
      active: actuator.re_evaluation?.active ?? false,
      skipped: actuator.re_evaluation?.skipped ?? false,
      interval: {
        start: actuator.re_evaluation?.interval?.start ?? null,
        end: actuator.re_evaluation?.interval?.end ?? null
      }
    }
  };
}

const weatherText = input.weather ?? "";

return [
  {
    json: {
      run_id: input.meta?.run_id ?? null,
      adr: $input.first().json.meta.adr,
      triggered_at: $input.first().json.meta.triggered_at ?? null,
      mode: $input.first().json.crop.mode,

      actuators: {
        pump: extractActuator($input.first().json.actuators[0]),
