      },

      weather: {
        precipitation_probability: $input.first().json.weather.precipitation_probability,
        summary: $input.first().json.weather.summary ,
      },

    }
  }
];

for (const item of $input.all()) {
  try {
    // 1. Get the raw string from the AI output
    const rawText = item.json.output;

    // 2. Split by '||' and grab the second part (index 1)
    const jsonString = rawText.split('||')[1].trim();

    // 3. Parse the extracted string into a real JSON object
    const parsedData = JSON.parse(jsonString);

    // 4. Extract ONLY the boolean value and save it
    item.json.take_picture = parsedData.take_picture;

